import sqlite3

DATABASE_PATH = "support.db"


def get_ticket_history_summary(ticket_id: int) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        ticket_row = database_connection.execute(
            "SELECT id, subject, status, owner_agent_id FROM tickets WHERE id = ?",
            (ticket_id,),
        ).fetchone()
        if ticket_row is None:
            return {"error": "Ticket not found"}
        comment_rows = database_connection.execute(
            "SELECT author, body, created_at FROM comments WHERE ticket_id = ? ORDER BY created_at",
            (ticket_id,),
        ).fetchall()
        return {
            "ticket": dict(ticket_row),
            "comments": [dict(comment_row) for comment_row in comment_rows],
        }
    finally:
        database_connection.close()
